  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Adiphenine, a lipophilic tertiary amine closely related to the query, readily crosses the BBB in mice and rats, with brain concentrations 4–15 times higher than blood, demonstrating meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Methadone, another lipophilic tertiary amine, readily crosses the BBB in rats with a brain/plasma ratio of 4.7 after subcutaneous dosing.",
